ator-results .viability{margin-top:10px;padding:11px 12px}.calculator-results>.btn{min-height:42px;border-radius:10px}.calculator-layout>div:first-child>.form-card{padding:17px 18px}.calculator-layout>div:first-child>.form-card:first-child{border-color:#c8ddfc;background:linear-gradient(180deg,#fbfdff,#fff)}.calculator-layout>div:first-child>.form-card:not(:first-child) .form-card__title{font-size:13px;margin-bottom:12px}.calculator-layout .info-note{font-size:10px}.calculator-layout .stat-box{background:#f8fbff;border-color:#dce8f7}.calculator-actions{margin-top:12px;padding:10px;border:1px solid #dbe8fb;border-radius:12px;background:#fff;box-shadow:0 4px 14px rgba(20,45,85,.06)}@media(max-width:1100px){.calculator-layout{grid-template-columns:minmax(360px,.9fr) minmax(420px,1.1fr)}}@media(max-width:700px){.calculator-results{position:static;box-shadow:none}.calculator-actions{padding:0;border:0;background:transparent;box-shadow:none}.calculator-results .result-card--highlight{grid-column:auto}.calculator-results .result-card--highlight strong{font-size:27px}}.margin-control{margin-top:10px;border:1px solid #cfe0f6;border-radius:12px;background:#fff;padding:13px 14px}.margin-control__head{display:flex;align-items:center;justify-content:space-between;gap:12px}.margin-control__head strong,.margin-control__head small{display:block}.margin-control__head strong{font-size:13px;color:var(--ink)}.margin-control__head small{margin-top:3px;color:var(--muted);font-size:10px}.margin-control output{min-width:52px;border-radius:8px;background:#eaf9f1;color:#087b4d;padding:7px 9px;text-align:center;font-size:16px;font-weight:750}.margin-control input[type=range]{display:block;width:100%;height:5px;margin:16px 0 8px;accent-color:var(--green);cursor:pointer}.margin-control__scale{display:flex;justify-content:space-between;gap:8px;color:var(--muted);font-size:9px}.margin-control .field__error{display:block;margin-top:7px}@media(max-width:700px){.margin-control__scale span:nth-child(2){display:none}}</style>
